import{_ as n,o as a,c as t,a3 as o}from"./chunks/framework.BK6ObQf6.js";const m=JSON.parse('{"title":"Connect Machines in a Zone","description":"","frontmatter":{},"headers":[],"relativePath":"guide/zones.md","filePath":"guide/zones.md","lastUpdated":1794404584000}'),s={name:"guide/zones.md"};function i(r,e,d,c,l,h){return a(),t("div",{"data-pagefind-body":!0},e[0]||(e[0]=[o(`<h1 id="connect-machines-in-a-zone" tabindex="-1">Connect Machines in a Zone <a class="header-anchor" href="#connect-machines-in-a-zone" aria-label="Permalink to &quot;Connect Machines in a Zone&quot;">​</a></h1><p>A zone is a virtual IPv4 network shared by a group of machines. Each machine that joins receives an address on the network, and applications reach other members through a local SOCKS5 proxy or, in VLAN mode, directly at their virtual addresses.</p><p>Zones are private by default. A private zone is not listed anywhere: only machines that are given its ID can join. Administrators can create public zones, which appear in the <em>Public zones</em> view on the website and in <code>linksocks zone list</code>; anyone who sees a public zone can join it and reach the services its members expose.</p><p>Open <a href="https://l.zetx.tech/zones" target="_blank" rel="noreferrer">Zones</a> on the website to browse public zones, view members and copy a join command. Browsing and joining do not require an account; signed-in users land on <strong>My zones</strong>, which lists the zones they created, and can switch to <strong>Public zones</strong> to see every public zone; there is no combined list. Zone IDs are lowercase UUIDs.</p><h2 id="before-you-connect" tabindex="-1">Before You Connect <a class="header-anchor" href="#before-you-connect" aria-label="Permalink to &quot;Before You Connect&quot;">​</a></h2><ul><li>Use a LinkSocks CLI build that includes <code>zone</code>. There is no Python library API; installing the Python bindings does not provide a <code>Zone</code> class.</li><li>The default join mode runs a local SOCKS5 proxy and needs no special privileges. The optional <code>--vlan</code> mode needs an L2 TAP interface and works on Linux (with <code>/dev/net/tun</code> and the <code>ip</code> command) and on Windows (with a TAP-Windows6 adapter); both need root or administrator privileges.</li><li>Choose a zone network that does not overlap any machine&#39;s existing LAN, VPN, container networks or other routes. The client checks interface addresses on every platform, and all IPv4 routing tables on Linux, excluding default routes.</li><li>Proxy mode runs on Linux, macOS and Windows.</li></ul><p>Linux has been verified end to end with real TAP interfaces and with the proxy mode. The Windows TAP path and the macOS proxy path compile; macOS cannot run <code>--vlan</code> (it only offers L3 tunnels) and the Windows TAP path has not been verified on a Windows machine yet.</p><p>Proxy mode carries TCP streams and UDP datagrams (SOCKS5 UDP ASSOCIATE) and creates no interface, so ICMP and other IP protocols are unavailable. <code>--vlan</code> carries complete Ethernet frames: ARP, ICMP/ping, TCP, UDP, broadcast (UDP broadcast and Wake-on-LAN magic packets), multicast and raw Ethernet frames travel between members like on a physical network segment. The VLAN interface MTU is 1500.</p><p>Neither mode provides IPv6, P2P direct connections, DNS, LAN subnet sharing or a default internet route. Use a member&#39;s virtual IP or, in proxy mode, its member name instead of relying on LAN discovery.</p><h2 id="create-a-network" tabindex="-1">Create a Network <a class="header-anchor" href="#create-a-network" aria-label="Permalink to &quot;Create a Network&quot;">​</a></h2><ol><li>Open <code>/zones</code> on your linksocks.js website and sign in.</li><li>Select <strong>Create zone</strong>.</li><li>Enter a <strong>Zone name</strong>, <strong>IPv4 network (CIDR)</strong> and <strong>Member limit</strong>.</li><li>Choose the visibility: <strong>Private</strong> (the default) or, if you are an administrator, <strong>Public</strong>.</li><li>Select <strong>Create zone</strong>.</li></ol><p>Names contain 1–64 characters. The entire network must be inside an RFC1918 private range: <code>10.0.0.0/8</code>, <code>172.16.0.0/12</code> or <code>192.168.0.0/16</code>. Prefixes from <code>/16</code> through <code>/30</code> are accepted. The member limit is 2–256 and must fit the usable addresses: a <code>/30</code> fits 2 members, a <code>/29</code> fits 6, and a <code>/24</code> fits 254. Network and broadcast addresses are not assigned.</p><p>New zones are private: they are not listed anywhere, and only machines you give the ID to can join. Only administrators can create public zones. A public zone is listed on the website and in <code>linksocks zone list</code>, and anyone who sees it can join and reach the services its members expose, so share its ID deliberately and make sure each member&#39;s firewall exposes only the intended services.</p><p>Signed-in users create zones and delete their own zones; administrators can delete any zone. Deleting a zone disconnects every member and releases all addresses; it cannot be undone.</p><h2 id="connect-each-machine" tabindex="-1">Connect Each Machine <a class="header-anchor" href="#connect-each-machine" aria-label="Permalink to &quot;Connect Each Machine&quot;">​</a></h2><ol><li>Find the zone on <code>/zones</code> and select <strong>Copy command</strong>. For a public zone, the ID and command are masked until you tick the confirmation that you have checked the machine&#39;s firewall; <strong>Copy command</strong> opens the same warning first. If the browser does not allow automatic copying, the command is selected so you can press Ctrl+C.</li><li>Run the copied command on each machine. Proxy mode needs no elevation; <code>--vlan</code> must run as root. Keep the command running. Its <code>Joined</code> line shows the assigned virtual IP, the interface in VLAN mode and the online peer count.</li><li>Use a member&#39;s virtual IP with your application, or its member name in proxy mode. The service must listen on its virtual IP in VLAN mode or on its loopback in proxy mode, and its firewall must allow the connection.</li></ol><p>The join command takes a lowercase zone UUID. Use <code>--name</code> to replace the hostname shown in the member list.</p><h3 id="proxy-mode-default" tabindex="-1">Proxy Mode (Default) <a class="header-anchor" href="#proxy-mode-default" aria-label="Permalink to &quot;Proxy Mode (Default)&quot;">​</a></h3><p><code>linksocks zone join &lt;zone-id&gt;</code> starts a local SOCKS5 proxy on <code>127.0.0.1:6080</code> and prints its address:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SOCKS5 proxy listening on 127.0.0.1:6080</span></span></code></pre></div><p>Change the port with <code>--socks-port</code>; <code>--socks-port 0</code> disables the listener. Applications address members by virtual IP or by name and should let the proxy resolve names:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --socks5-hostname</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 127.0.0.1:6080</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://10.88.0.2:8080/</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --socks5-hostname</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 127.0.0.1:6080</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://machine-b:8080/</span></span></code></pre></div><p>Proxy mode carries TCP and UDP (SOCKS5 UDP ASSOCIATE). A connection to a member&#39;s virtual IP arrives at the service listening on that member&#39;s <code>127.0.0.1</code>, so no public interface or inbound port is needed. There is no interface, so ICMP and protocols other than TCP and UDP are not carried.</p><h3 id="vlan-mode-vlan" tabindex="-1">VLAN Mode (<code>--vlan</code>) <a class="header-anchor" href="#vlan-mode-vlan" aria-label="Permalink to &quot;VLAN Mode (\`--vlan\`)&quot;">​</a></h3><p>With <code>--vlan</code>, the client creates an L2 TAP interface — <code>lz0</code> by default, or another name via <code>--interface</code> — with MTU 1500. Machines behave like hosts on one Ethernet segment: ARP, ICMP/ping, TCP, UDP, UDP broadcast, Wake-on-LAN magic packets, multicast and raw Ethernet frames all pass between members. Applications connect directly to member virtual IPs with no proxy configuration. Adding <code>--socks-port</code> in VLAN mode additionally starts the SOCKS5 listener.</p><p>When joining several zones on one machine, give each join a distinct interface name and use non-overlapping networks.</p><h3 id="windows-and-macos" tabindex="-1">Windows and macOS <a class="header-anchor" href="#windows-and-macos" aria-label="Permalink to &quot;Windows and macOS&quot;">​</a></h3><p><code>--vlan</code> needs a layer-2 (Ethernet) virtual adapter, because the zone protocol treats each member&#39;s adapter MAC as its identity on the segment and filters inbound frames by it. That adapter exists on Linux out of the box; Windows needs a driver, and macOS cannot do layer 2 at all.</p><p><strong>Windows (TAP-Windows6).</strong> Install the TAP-Windows6 driver and add one adapter per zone, then join with <code>--vlan</code> from an elevated shell:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># One-time: install tap-windows6 from https://build.openvpn.net/downloads/releases/</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># (the installer adds an adapter). Repeat &quot;Add a new TAP virtual ethernet</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># adapter&quot; in the installer, or run addtap.bat, for each extra zone.</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Join from an elevated PowerShell or Command Prompt</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">linksocks zone join </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">zone</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">id</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">vlan</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Several adapters: name the one to use</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">linksocks zone join </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">zone</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">id</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">vlan </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">interface </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Local Area Connection 2&quot;</span></span></code></pre></div><p>The client picks the first TAP-Windows6 adapter when <code>--interface</code> is omitted, pins its MAC to the machine&#39;s member MAC (Windows applies that on adapter restart, which the client performs), enables the adapter, and sets the member address. All of it needs administrator rights, just as Linux needs root. Without an elevated shell it stops with that message instead of half-working.</p><p><strong>macOS</strong> only offers L3 tunnels (utun), so <code>--vlan</code> is not available: join without it and use the SOCKS5 proxy, which reaches members by address or name.</p><p><strong>WSL2</strong> is Linux, so <code>--vlan</code> works there for programs running inside WSL. Windows programs still cannot join that segment: point them at a proxy, which WSL2 forwards on <code>127.0.0.1</code>.</p><h3 id="command-reference" tabindex="-1">Command Reference <a class="header-anchor" href="#command-reference" aria-label="Permalink to &quot;Command Reference&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Command or option</th><th>Use</th></tr></thead><tbody><tr><td><code>zone list</code></td><td>List public zone IDs, names, networks and member limits</td></tr><tr><td><code>zone join &lt;zone-id&gt;</code></td><td>Join in the foreground; start a SOCKS5 proxy or, with <code>--vlan</code>, a TAP interface</td></tr><tr><td><code>zone leave &lt;zone-id&gt;</code></td><td>Release this machine&#39;s address and stop its active join</td></tr><tr><td><code>--url</code>, <code>-u</code></td><td>Coordinator website; defaults to <code>https://l.zetx.tech</code></td></tr><tr><td><code>--identity</code></td><td>Path to the local machine key; use the same file for join and leave</td></tr><tr><td><code>--name</code></td><td>Machine name for join; defaults to the hostname</td></tr><tr><td><code>--socks-port</code></td><td>Local SOCKS5 proxy port, default <code>6080</code>; <code>0</code> disables the listener; with <code>--vlan</code> the proxy starts only when the flag is given</td></tr><tr><td><code>--vlan</code></td><td>Use an L2 TAP interface instead of proxy mode (Linux with <code>/dev/net/tun</code>, or Windows with TAP-Windows6; root or administrator)</td></tr><tr><td><code>--interface</code></td><td>TAP interface name for <code>--vlan</code>; default <code>lz0</code> on Linux, the first TAP-Windows6 adapter on Windows</td></tr><tr><td><code>--no-env-proxy</code>, <code>-E</code></td><td>Ignore environment proxy settings</td></tr><tr><td><code>--ech</code></td><td>Encrypted Client Hello for the coordinator connection; default <code>auto</code></td></tr><tr><td><code>--debug</code>, <code>-d</code></td><td>Show debug logs; <code>-dd</code> adds trace logs (streams, datagrams, firewall drops, coordinator pings)</td></tr></tbody></table><p>Run these subcommands under <code>linksocks</code>. <code>--url</code> accepts HTTP(S) and WebSocket URLs. Use HTTPS for a remote coordinator. The <code>--name</code>, <code>--socks-port</code>, <code>--vlan</code> and <code>--interface</code> options belong to <code>join</code>; the other listed options are shared by all zone commands.</p><p>A joined machine logs what it does: joining and the assigned address, later peer-count changes, the SOCKS5 listener and, in VLAN mode, the interface. Add <code>-d</code> to see why traffic flows or not — an opened stream, a refused one with its reason (blocked by the zone firewall, the peer is offline, the local service is unreachable) — and <code>-dd</code> for per-frame detail such as datagrams and firewall drops.</p><h2 id="manage-a-zone" tabindex="-1">Manage a Zone <a class="header-anchor" href="#manage-a-zone" aria-label="Permalink to &quot;Manage a Zone&quot;">​</a></h2><p>The zone owner and site administrators manage members and settings from <code>/zones</code>:</p><ul><li><strong>View members</strong> shows every machine with its name, status, virtual IP and identity. Online machines can be kicked; offline machines with retained addresses can be removed. Both disconnect a running join immediately and release its address. The removed process exits with <code>Removed from the zone.</code> and does not reconnect automatically; running the join command again lets the machine rejoin.</li><li><strong>Settings</strong> edits the <strong>welcome message</strong> and the <strong>firewall rules</strong>. The welcome message (up to 512 characters) is shown on machines when they join the zone.</li><li>A zone holds up to 64 ordered firewall rules. Each rule matches a source and destination IPv4 network, a source and destination port (any, one port or a range), a protocol (<code>any</code>, <code>tcp</code>, <code>udp</code>, <code>icmp</code>, <code>arp</code>) and an allow or deny action. The first matching rule decides; traffic that matches no rule follows the zone&#39;s default policy (allow or deny).</li></ul><p>Rule enforcement differs by mode. In proxy mode the relay and both members check every TCP connection and UDP datagram against the rules. In <code>--vlan</code> mode the relay cannot see inside Ethernet frames, so the receiving members filter every frame against their copy of the rules. Rules with a specific source port match VLAN traffic only, because proxy-mode streams carry no source port to match.</p><h2 id="keep-your-machine-identity" tabindex="-1">Keep Your Machine Identity <a class="header-anchor" href="#keep-your-machine-identity" aria-label="Permalink to &quot;Keep Your Machine Identity&quot;">​</a></h2><p>The first join generates an Ed25519 identity locally. Its private key stays on the machine. The default file is <code>linksocks/zone.key</code> under the operating system&#39;s user configuration directory: typically <code>~/.config</code> on Linux, <code>~/Library/Application Support</code> on macOS, and <code>%AppData%</code> on Windows.</p><p>The client creates the key file with mode <code>0600</code> and any missing parent directories with mode <code>0700</code> on Unix. It rejects an existing key file that grants any group or other-user permissions. On Windows, restrict access through the file&#39;s access controls. Do not copy one identity to several machines: a zone accepts only one active connection per identity.</p><p>Use an explicit absolute <code>--identity</code> path if you need a predictable location when running with elevated privileges. Changing the user or key file changes the machine identity. Keep the original file to reconnect to a retained address or release it later.</p><p>In VLAN mode the interface MAC address is derived from this identity and stays the same across reconnects, so peer ARP caches remain valid.</p><h2 id="disconnect-or-recover-after-an-outage" tabindex="-1">Disconnect or Recover After an Outage <a class="header-anchor" href="#disconnect-or-recover-after-an-outage" aria-label="Permalink to &quot;Disconnect or Recover After an Outage&quot;">​</a></h2><p>Press <strong>Ctrl+C</strong> in the running join command to leave and release its address. To stop it from another terminal, run <code>zone leave</code> with the same zone ID, coordinator URL and identity file. This also disconnects a join running in another process. A later join may receive a different address.</p><p>After a network outage or an abrupt process exit, the website marks the machine <strong>Offline</strong> and retains its address for 24 hours. Offline leases still count toward the member limit. A running client automatically reconnects after transport failures; restarting with the same identity within the lease period also retains the address. Explicit leave releases the lease immediately. A machine removed by an owner or administrator stops instead of reconnecting.</p><p>Deleting a zone disconnects every member and releases all addresses. This cannot be undone. To delete it, select <strong>Delete zone</strong> on <code>/zones</code> and confirm. Clients stop when the zone is deleted or their membership is explicitly removed.</p><h2 id="understand-what-is-encrypted" tabindex="-1">Understand What Is Encrypted <a class="header-anchor" href="#understand-what-is-encrypted" aria-label="Permalink to &quot;Understand What Is Encrypted&quot;">​</a></h2><p>Each connection uses a fresh X25519 exchange key and XChaCha20-Poly1305 packet encryption between members. Reconnection replaces the exchange key. With the coordinator providing the correct peer directory, the relay forwards encrypted payloads and cannot read them.</p><p>You trust the coordinator to supply machine identities, peer keys and address assignments. This does not protect against a malicious coordinator replacing the peer directory. The coordinator can see membership, source and destination virtual IPs, packet sizes and timing; in VLAN mode it can also see the Ethernet addresses in the frames it forwards.</p><h2 id="troubleshoot-a-connection" tabindex="-1">Troubleshoot a Connection <a class="header-anchor" href="#troubleshoot-a-connection" aria-label="Permalink to &quot;Troubleshoot a Connection&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Message or symptom</th><th>What to check</th></tr></thead><tbody><tr><td><code>administrator privileges required</code></td><td><code>--vlan</code> needs root; run the join in an elevated terminal and check that <code>/dev/net/tun</code> exists</td></tr><tr><td><code>zone --vlan needs a layer-2 virtual adapter</code></td><td>VLAN mode needs Linux or a TAP-Windows6 adapter on Windows; macOS uses proxy mode</td></tr><tr><td><code>configure zone interface</code></td><td>Check that the platform&#39;s network commands are available and allowed</td></tr><tr><td><code>Note: --interface applies to --vlan mode</code></td><td>Drop <code>--interface</code> in proxy mode, or add <code>--vlan</code> if you want a TAP interface</td></tr><tr><td><code>overlaps</code></td><td>Choose a zone whose CIDR does not overlap the reported interface or route</td></tr><tr><td><code>Identity is already online</code></td><td>Stop the other join for this identity, or use <code>zone leave</code> with its key before joining again</td></tr><tr><td><code>Zone is full</code></td><td>Offline leases also occupy slots; their owners can leave, or wait for the 24-hour lease to expire</td></tr><tr><td><code>Zone not found</code></td><td>The zone was deleted or the ID is wrong; copy the ID and URL from the same website</td></tr><tr><td><code>Zone service is not configured</code></td><td>The operator must configure the Worker&#39;s <code>DB</code> and <code>ZONE</code> bindings; see the <a href="https://github.com/linksocks/linksocks.js#zone-networks" target="_blank" rel="noreferrer">Worker setup</a></td></tr><tr><td><code>Removed from the zone.</code></td><td>An owner or administrator removed this machine; run the join command again to rejoin, or contact them</td></tr><tr><td>A connection through the proxy is refused</td><td>Check the zone&#39;s firewall rules and default policy with the zone owner</td></tr><tr><td>Joined, but an application cannot connect</td><td>Check the peer is online, the destination is its virtual IP or name, and that the SOCKS client uses remote name resolution (<code>--socks5-hostname</code>); in VLAN mode check the service listens on its virtual IP and the local firewall permits access</td></tr></tbody></table><h2 id="a-verified-linux-run" tabindex="-1">A Verified Linux Run <a class="header-anchor" href="#a-verified-linux-run" aria-label="Permalink to &quot;A Verified Linux Run&quot;">​</a></h2><p>This output comes from two Linux network namespaces connected through a local Worker, using a <code>/29</code> network with a six-member limit. One run exercised the default proxy mode; the other used <code>--vlan</code> with real TAP interfaces and checked ARP, ICMP, TCP, UDP, reconnect and leave. The test zones were deleted after verification; copy your own zone&#39;s command from the website.</p><h3 id="vlan-mode-with-real-tap-interfaces" tabindex="-1">VLAN Mode with Real TAP Interfaces <a class="header-anchor" href="#vlan-mode-with-real-tap-interfaces" aria-label="Permalink to &quot;VLAN Mode with Real TAP Interfaces&quot;">​</a></h3><p>The two join processes reported:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Joined Zone network test (9b89a4eb-8dff-4a3f-acab-2f192349d9a1, private) as 10.249.231.1 on lz0; 0 peer(s) online.</span></span>
<span class="line"><span>Joined Zone network test (9b89a4eb-8dff-4a3f-acab-2f192349d9a1, private) as 10.249.231.2 on lz0; 1 peer(s) online.</span></span></code></pre></div><p>ARP resolution, ICMP at the interface MTU, a TCP transfer and a UDP echo all passed:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PING 10.249.231.2 (10.249.231.2) 1472(1500) bytes of data.</span></span>
<span class="line"><span>1480 bytes from 10.249.231.2: icmp_seq=1 ttl=64 time=0.938 ms</span></span>
<span class="line"><span>1480 bytes from 10.249.231.2: icmp_seq=2 ttl=64 time=0.775 ms</span></span>
<span class="line"><span>1480 bytes from 10.249.231.2: icmp_seq=3 ttl=64 time=0.687 ms</span></span>
<span class="line"><span></span></span>
<span class="line"><span>--- 10.249.231.2 ping statistics ---</span></span>
<span class="line"><span>3 packets transmitted, 3 received, 0% packet loss, time 2055ms</span></span>
<span class="line"><span>rtt min/avg/max/mdev = 0.687/0.800/0.938/0.103 ms</span></span>
<span class="line"><span>TCP: 262144 bytes, SHA-256 81d0141af58569f91edf2d036b67a6b82c062d1829fd93aec50ed96b4773d225</span></span>
<span class="line"><span>UDP: 1200-byte echo verified.</span></span></code></pre></div><p>After an abrupt exit, the second machine rejoined with its original address. A firewall deny rule for ICMP stopped pings until the rule was cleared. Explicit leave then stopped the running join and released that lease:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Rejoin retained 10.249.231.2.</span></span>
<span class="line"><span>Firewall: an ICMP deny rule stopped pings in VLAN mode.</span></span>
<span class="line"><span>Firewall: clearing the rule restored pings.</span></span>
<span class="line"><span>Left zone 9b89a4eb-8dff-4a3f-acab-2f192349d9a1.</span></span>
<span class="line"><span>Leave disconnected the running machine and released its IPv4 lease.</span></span>
<span class="line"><span>Signal-driven leave removed the final membership.</span></span>
<span class="line"><span>PASS: real TAP Ethernet (ARP), ICMP, TCP, UDP, reconnect and leave.</span></span></code></pre></div><h3 id="proxy-mode" tabindex="-1">Proxy Mode <a class="header-anchor" href="#proxy-mode" aria-label="Permalink to &quot;Proxy Mode&quot;">​</a></h3><p>Two members joined the same zone through a local Worker. Machine B served TCP and UDP on its loopback. A SOCKS5 client on machine A reached it by virtual IP and by member name; a deny rule blocked a new TCP connection until it was cleared:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SOCKS5 proxy listening on 127.0.0.1:20485</span></span>
<span class="line"><span>TCP: curl --socks5-hostname reached machine-b by virtual IP and by name.</span></span>
<span class="line"><span>UDP: echoed 16 bytes through SOCKS5 UDP ASSOCIATE.</span></span>
<span class="line"><span>Firewall: a deny rule stopped a new TCP connection through the proxy.</span></span>
<span class="line"><span>Firewall: clearing the rule restored access.</span></span>
<span class="line"><span>PASS: proxy-mode SOCKS5 TCP and UDP between two members.</span></span></code></pre></div>`,67)]))}const u=n(s,[["render",i]]);export{m as __pageData,u as default};
